// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address to, uint256 amount, address caller) public {
        vm.assume(to != address(0));
        vm.assume(amount > 0);
        vm.prank(caller);
        bool ok = c.transfer(_toArray(to), _toArr(amount));
        assertTrue(ok);
    }
    function _toArray(address a) internal pure returns (address[] memory arr) {
        arr = new address[](1);
        arr[0] = a;
    }
    function _toArr(uint256 v) internal pure returns (uint256[] memory arr) {
        arr = new uint256[](1);
        arr[0] = v;
    }
}
